    content: `我儿子去年9月上的小学一年级。说实话，在他入学之前，我比他还紧张。到处问过来人"要不要提前学拼音""要不要学写字""书包买什么样的"，越问越焦虑。

后来我发现，很多家长的焦虑都集中在"学什么"上，比如拼音要不要提前学、20以内加减法要不要会、识字量要达到多少。但其实，真正影响孩子一年级适应的，不是知识储备，而是习惯和心理准备。

这篇文章是我陪儿子走过幼小衔接的真实经验总结。不是什么专家理论，就是一个普通家长的踩坑记录和心得。

![入学准备照片：儿子开学第一天在校门口的照片，背着新书包，有点紧张又有点兴奋](/images/blog/yinianji-ruxue-zhunbei.jpg)

## 学习习惯准备（最重要）

一年级和幼儿园最大的区别是什么？不是学的东西更难了，而是有了"上课"这个概念。幼儿园以玩为主，小学以学为主。很多孩子一年级不适应，根本原因就是坐不住。

我从入学前两个月开始，每天让儿子练习"安静坐20分钟"。不是让他写作业或者学习，就是安安静静地坐着，可以画画、可以看绘本、可以搭积木，但不能离开座位，不能看电视，不能玩玩具。

一开始他5分钟就坐不住了，要喝水要上厕所要吃东西。我没批评他，就是温和地提醒"我们说好了要坐20分钟的"。第一周每天只能坐8-10分钟，第二周慢慢到15分钟，到入学前一周终于能坐满20分钟了。

这个训练看起来简单，但效果非常明显。开学后老师说他是班上坐得最稳的孩子之一，上课注意力很集中。我后来跟其他家长聊天，发现好几个孩子上课坐不住、到处跑，老师每天都要提醒好几次。

除了坐得住，还有两个习惯也很重要。一个是自己的事情自己做，比如整理书包、削铅笔、收拾桌面。幼儿园这些东西都是老师帮忙的，小学需要孩子自己来。我入学前一个月就让儿子自己整理书包，我检查但不帮忙。一开始他经常忘带东西，后来慢慢就记住了。

另一个是按时作息。幼儿园早上8点去都行，小学一般7点50到校。我从入学前一个月开始调整作息，晚上9点睡觉，早上6点半起床。这个作息一直保持到现在。

## 心理准备（经常被忽略）

很多家长忽略了心理准备。孩子从幼儿园到小学，环境变了、老师变了、同学变了、规矩变了，心里肯定会有不安全感。

我做了一件事，就是带儿子去学校门口转了好几次。告诉他"这就是你以后上学的地方"，让他看看学校的大门、操场、教学楼，熟悉一下环境。开学第一天他虽然还是有点紧张，但至少不是完全陌生的感觉。

还有一件事我觉得很有用。我在入学前一个月，每天跟儿子聊5分钟关于小学的事。不是讲大道理，就是随便聊聊。"小学有课间十分钟可以出去玩""小学中午在学校吃饭""小学会有很多新同学"。让他对小学生活有一个基本的了解，减少未知带来的恐惧。

儿子入学第一天回来，我跟他说"今天怎么样"，他说"挺好玩的，就是坐的时间太长了"。听到这句话我放心了不少，至少他没有排斥。

## 知识准备（不需要太多）

关于知识储备，我的建议是"够用就行，不要过度"。

拼音：不需要完全学会，但最好认识声母和韵母，知道拼音是怎么回事。我用拼音注音工具打印了一份声母韵母表贴在墙上，儿子每天看一眼，入学前基本能认全了。不需要会拼，能认就行。

识字：不需要认识很多字，但最好能认自己的名字、常见的水果名称、家庭成员称谓这些基础字。我大概教了100多个常用字，不多，但够用。

数学：20以内的数数会就行，不需要会加减法。入学后老师会从头教的，提前学了反而可能因为"我已经会了"而不认真听。

写字：不需要会写很多字，但最好会写自己的名字，握笔姿势要正确。握笔姿势一旦养成错误的习惯，以后很难改。我专门买了一套握笔器，练习了大概两周。

![知识准备照片：墙上贴着的声母韵母表，儿子用拼音注音工具打印的，旁边是他的名字练习](/images/blog/yinianji-zhunbei-zhipin.jpg)

## 物品准备（别买太多）

书包：买一个自重轻的，不要太大。一年级课本不多，太大的书包反而累赘。我买了一个能放进课桌抽屉的小书包，很实用。

铅笔：HB的木杆铅笔，不要买自动铅笔。一年级孩子写字用力不均匀，自动铅笔芯容易断。

橡皮：买普通的4B橡皮就行，不要买那种花里胡哨的玩具橡皮。

文具盒：简单的布笔袋就好，不要买铁的，上课打开会响。

水杯：买一个不容易漏水的，最好是能单手开盖的。

这些基本就够了。我见过有家长买了那种多功能文具盒，里面什么都有，结果上课的时候孩子光玩文具了。

## 时间规划建议

入学前两个月：开始调整作息，练习安静坐20分钟，教孩子自己整理物品。

入学前一个月：熟悉学校环境，认识基础汉字和声母韵母，练习写自己的名字。

入学前一周：准备好所有物品，调整好作息，跟孩子聊聊对小学的期待。

入学后第一周：多鼓励少批评，孩子可能会累会哭会不想去上学，这都是正常的。我儿子第一周回来就哭了两次，说"太累了，不想去了"。我没有批评他，就是抱了抱他，说"妈妈知道你累了，休息一下明天就好了"。第二周就好了。

入学后第一个月：重点培养按时完成作业的习惯。一年级作业不多，但一定要养成"回家先写作业"的习惯。

幼小衔接不是一场考试，不需要让孩子提前学很多东西。把习惯和心理准备好，比多认几百个字有用得多。我儿子现在一年级快结束了，适应得很好，成绩也在班里中上。回想起来，我觉得最正确的决定就是没有提前教他太多知识，而是把时间花在了习惯培养上。`,
