    content: `"妈妈，这道应用题我读不懂..."儿子拿着数学作业本，一脸茫然地看着我。

我拿过来看了一眼："小明有12个苹果，给了小红3个，又买了5个，现在有多少个？"

说实话，这种题对大人来说简单得不能再简单，但对二年级的孩子来说，却是一道需要跨越多个认知台阶的难题。首先要理解"给了"是减少，"买了"是增加，然后还要确定运算顺序。

儿子期中考试应用题扣了18分，占数学总失分的60%。那天晚上我盯着试卷看了很久，心想如果不解决这个问题，数学成绩永远上不去。

三个月后，儿子的应用题只扣了2分。今天我把这套方法完整分享出来。

【作业实拍：儿子期中考试的数学试卷，应用题部分红笔批改的痕迹清晰可见】

## 儿子为什么觉得应用题难？

为了搞清楚这个问题，我专门花了一个周末观察儿子做题的过程。我坐在旁边不说话，就看着他怎么读题、怎么思考、怎么下笔。

我发现问题主要有三个。

第一个问题是读不懂题意。应用题不像计算题那样直接给出算式，需要用文字理解数量关系。儿子看到大段文字就发怵，有时候还没读完就开始瞎猜答案。我问他"你读懂题目了吗"，他说"大概懂了"，结果一做就错。

第二个问题是找不到关键信息。题目里有些信息是干扰项，有些是核心条件。儿子往往分不清主次，要么漏掉关键信息，要么被干扰信息带偏。有一次题目里有个数字根本用不到，他硬是给算进去了，结果答案完全不对。

第三个问题是不会列式。他有时候理解了题意，但不知道怎么转化成数学算式。这是从"语文理解"到"数学表达"的跨越，很多孩子卡在这里。儿子经常跟我说"我知道答案是多少，但就是不知道怎么写算式"。

我后来查了一些资料，北师大有个研究说小学三年级学生应用题错误率高达45%，其中70%的错误源于"题意理解不清"而不是计算错误。看到这个数据我反而松了口气，原来不是我儿子一个人这样。

## 我教儿子的四步法

**第一步：慢读圈画，找出关键信息**

我教儿子的第一招就是慢读加圈画。拿到应用题不要急着动笔，先大声读两遍，然后用不同符号圈出关键信息。圈出数字，知道有什么数据；横线画出问题，知道要求什么；波浪线画出关键词，知道怎么算。

比如这道题：小明有12个苹果，给了小红3个，又买了5个，现在有多少个？

圈画之后一目了然：已知12、3、5，求现在有多少，给了表示减，买了表示加。

刚开始儿子圈得乱七八糟，什么都圈。我教他"只圈数字和问题"，慢慢就找准了。现在他拿到题先圈再算，已经形成习惯了。

![应用题解题示例：圈画关键词，画线段图理解数量关系](/images/blog/yingyongti-example.jpg)

**第二步：画图示意，理清数量关系**

对于复杂一点的应用题，我让孩子画图。画图不是美术课，不需要好看，只需要清楚表达数量关系。

加减法的题画线段图，画一条线表示总数，分段表示增减。乘除法的题画阵列图，画格子表示倍数关系。比较题画对比图，上下对齐比较多少。路程题画路线图，画起点终点表示距离。

儿子最喜欢画线段图，他说画出来就明白了。确实，可视化是理解抽象数量关系的最好方法。我记得有一次他画完线段图之后突然说"妈妈我懂了"，那一刻我觉得这个方法真的管用。

**第三步：列式计算，注意单位**

画图理清关系后，就可以列式了。我让孩子养成一个习惯，先口头说一遍算式，确认无误再写下来。

比如上面那道题，口头说先减3再加5，就是12减3加5，然后列式12减3加5等于14。

特别注意单位。应用题往往有单位陷阱，比如前面是米后面是千米，或者前面是元后面是角。我让孩子养成习惯，算出答案后回头检查一下单位是否对应问题。有一次他算出答案是14，但题目问的是"多少元"，他写成了14个，这种错误太可惜了。

**第四步：验算答案，回归题意**

最后一步是验算，但验算不是简单重算一遍，而是把答案放回题目里验证。

比如算出现在有14个苹果，就验证12个给出去3个剩9个，再买5个确实是14个。这样验算既检查了计算，又检查了理解。儿子一开始觉得验算麻烦，后来有一次验算发现算错了，从此就主动验算了。

【对比照片：儿子三个月前后的应用题作业对比，前期错误率高，后期基本全对】

## 从扣18分到扣2分的过程

儿子二年级下学期，应用题是最大短板。我按照上面的四步法，每天陪他练2道应用题，坚持了一个学期。

第一个月重点练圈画关键信息。儿子一开始圈得乱七八糟，什么都圈。我教他只圈数字和问题，慢慢就找准了。那段时间我每天下班回来第一件事就是陪他练两道题，有时候他累了不想做，我就跟他商量先做一道，做完休息5分钟再做第二道。

第二个月重点练画图。从最简单的线段图开始，儿子画得歪歪扭扭，但数量关系清楚了。这个月应用题错误率从60%降到35%。我记得有一次他画完线段图之后突然说"妈妈我懂了"，那一刻我觉得这个方法真的管用。

第三个月重点练验算。儿子以前算出答案就完事，现在会主动验证。这个月应用题错误率降到15%。有一次他验算发现算错了，从此就主动验算了。

期末考试，数学应用题只扣了2分，总分96分，班级前10。拿到试卷那天他特别高兴，跟我说"妈妈我应用题全对了"。虽然我知道不是全对，但只扣2分已经进步很大了。

## 给家长的几点建议

第一个建议是从简单题开始。不要一上来就练复杂题，从一步计算的应用题开始，让孩子建立信心。等简单题熟练了，再逐步增加难度。我儿子就是从最简单的"小明有5个苹果，给了小红2个，还剩几个"这种题开始的。

第二个建议是每天2道，贵在坚持。应用题能力不是突击能练出来的，需要日积月累。每天2道，半年下来就是360道，足够形成解题思维。我有时候加班回来晚了，也会让他至少做一道，保持连续性很重要。

第三个建议是让孩子当小老师。让他把解题过程讲给你听，能讲清楚才是真懂了。我儿子特别喜欢当小老师，每次讲完还要问我"妈妈你听懂了没"，我就配合他说"听懂了，谢谢小老师"。

【真实对话截图：手机里存的和儿子的聊天记录，他发语音说"妈妈今天数学作业的应用题我都做对了！"】

应用题是小学数学的半壁江山，攻克这一关，数学成绩自然就上去了。我儿子就是个例子，从扣18分到扣2分，靠的不是天赋，而是方法加坚持。`,
